import{_ as s,a0 as p,w as u,s as d,ao as i,I as n,x as e,a1 as o,A as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const A=JSON.parse('{"title":"EndeavourOS：你對完美的 Arch 發行版的搜尋到此為止 | LCTT x X-CMD","titleTemplate":false,"description":"EndeavourOS：你對完美的 Arch 發行版的搜尋到此為止 | LCTT (202301) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"EndeavourOS：你對完美的 Arch 發行版的搜尋到此為止 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"EndeavourOS：你對完美的 Arch 發行版的搜尋到此為止 | LCTT (202301) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202301/20221221.0 ⭐️⭐️ EndeavourOS Your Search for Perfect Arch Distro Ends Here","title":"EndeavourOS：你對完美的 Arch 發行版的搜尋到此為止","tag":"202301","desc":""},"relativePath":"202301/20221221.0 ⭐️⭐️ EndeavourOS Your Search for Perfect Arch Distro Ends Here.md","filePath":"[post].md"}'),l={name:"202301/20221221.0 ⭐️⭐️ EndeavourOS Your Search for Perfect Arch Distro Ends Here.md"};function f(m,r,w,v,S,b){const t=p("Link");return u(),d("div",null,[r[33]||(r[33]=i('<h1 id="endeavouros-你對完美的-arch-發行版的搜尋到此為止" tabindex="-1">EndeavourOS：你對完美的 Arch 發行版的搜尋到此為止 <a class="header-anchor" href="#endeavouros-你對完美的-arch-發行版的搜尋到此為止" aria-label="Permalink to “EndeavourOS：你對完美的 Arch 發行版的搜尋到此為止”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202301/24/205819zhx7kx5899ra9ka9.jpg" alt=""></p><blockquote><p>我們整體點評了最近發佈的 EndeavourOS “Cassini”。</p></blockquote><p>每年，個人和小型團隊們推出了數以百計的 Linux 發行版。它們大多是 Debian、Ubuntu、Fedora 或 Arch Linux 的直接衍生品，再加上一些定製的東西。這也難怪每年都有因為缺乏貢獻、願景和堅持而死亡的發行版。</p><p>三年前，作為已停止的 Antergos 項目的延續，一個由貢獻者們組成的小團隊發起了 EndeavourOS 項目。從那時起，由於其安裝簡單，用户體驗和功能，它已經變得很受歡迎。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Xubuntu-22.04-with-Xfce-4.18-Desktop-2.jpg" alt="具備 Xfce 桌面的 EndeavourOS"></p><h3 id="點評-endeavouros" tabindex="-1">點評 EndeavourOS <a class="header-anchor" href="#點評-endeavouros" aria-label="Permalink to “點評 EndeavourOS”">​</a></h3><p>如果你曾經試過它，你就會很明顯地發現，他們花了很多心血來開發這個發行版。這個發行版的口號是成為一個面向大眾的 “通用” Arch Linux 發行版，摒棄了新用户對 Arch Linux 安裝的恐懼，以及使用 Arch 時的優越感。</p><p>如果你曾經嘗試過 EndeavourOS，你一定會 “感覺” 到作為一個 Arch 發行版，對最終用户來説，在桌面上執行的事情是多麼的 “容易”。</p><h4 id="安裝和可供選擇的桌面" tabindex="-1">安裝和可供選擇的桌面 <a class="header-anchor" href="#安裝和可供選擇的桌面" aria-label="Permalink to “安裝和可供選擇的桌面”">​</a></h4><p>通過 “獨有的” Calamares 安裝程序，它的安裝變得超級簡單。除此之外，EndeavourOS 團隊還特別注意在安裝步驟中為你提供了大部分的選項。例如，無需用户干預的臨場介質直接啓動。它會啓動歡迎屏幕。歡迎屏幕要做的事就是提供讓你在系統中安裝它所有必要選項。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/EndeavourOS-Welcome-Screen.jpg" alt="EndeavourOS 歡迎屏幕"></p><p>默認情況下，ISO 提供了一個輕量級的 Xfce 桌面。然而，EndeavourOS 也為你提供了各種桌面環境和窗口管理器（見下文）。而且它們都經過測試，可以正常工作。如果你在安裝過程中連接到了互聯網，你可以通過 Calamares 安裝程序來安裝這些。這意味着你不需要在基本的 Xfce 設置後重新安裝它們。</p><p>此外，如果你是一個資深用户，只想安裝一個基本的 Arch Linux，不需要任何桌面，那也是可以的。只要在安裝時使用 “<ruby>無桌面<rt>No desktop</rt></ruby>” 選項就可以了!</p><p>儘管 Arch Linux 最近創建了一個自動腳本 <code>archinstall</code> 來使安裝更容易，但通過 EndeavourOS 的 ISO 來獲得 Arch 的基本安裝仍然更快、更容易。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/EndeavourOS-installer-showing-22no-desktop22-and-other-options.jpg" alt="EndeavourOS 安裝程序顯示無桌面和其他選項"></p><p>此外，你可以在三個選項中選擇：GRUB、systemd-boot 或 “<ruby>無啓動器<rt>no bootloader</rt></ruby>”，這是 EndeavourOS “Cassini” 版本的亮點功能之一。此外，你還可以選擇你要安裝的軟件包（僅在線模式支持）。例如，你可能需要一個基本的系統來開始使用。或者，你可能想安裝一些與視頻/音頻或開發工作有關的應用程序。所有這些你都可以在這個版本中選擇。</p>',17)),n("p",null,[r[1]||(r[1]=e("安裝通過檢測我的測試機中安裝的其他操作系統而完成，很順利。在“Cassini” 版本中，該團隊還將 mkinitcpio 換成了 ",-1)),o(t,{href:"https://wiki.archlinux.org/title/Dracut"},{default:a(()=>[...r[0]||(r[0]=[e("dracut",-1)])]),_:1}),r[2]||(r[2]=e("，以獲得更好的性能，減少啓動相關問題的失敗。",-1))]),r[34]||(r[34]=i('<h4 id="xfce-旗艦版的桌面體驗" tabindex="-1">“Xfce” 旗艦版的桌面體驗 <a class="header-anchor" href="#xfce-旗艦版的桌面體驗" aria-label="Permalink to ““Xfce” 旗艦版的桌面體驗”">​</a></h4><p>第一次登錄後，你會再次看到歡迎程序，其中有一個 “安裝後” 可以做的項目列表。開發人員提供了一個非常周到的列表。這包括改變牆紙、更新 Arch 鏡像、安裝英偉達驅動等初始任務。許多 Linux 發行版都有一個歡迎程序，但我認為這個程序是一個完善的軟件包。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/After-install-items-in-Welcome-app.jpg" alt="歡迎應用中的安裝後項目"></p><p>默認的外觀是你能得到的定製的最好的 Xfce 桌面。通過定製，它成為一個外觀良好的發行版，遠非默認的 Xfce 可比。定製包括 GRUB 菜單、登錄屏幕和桌面等等。</p><p>Xfce 主菜單配置了更多的項目，終端略帶透明，使用 Qogir 圖標主題。所有這些變化都輔以令人驚歎的壁紙和 Arc-Darker 默認 Xfce 主題。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/EndeavourOS-22Cassini22-Desktop-with-Xfce-4.18.jpg" alt="EndeavourOS “Cassini” 桌面帶有 Xfce 4.18"></p><h4 id="性能" tabindex="-1">性能 <a class="header-anchor" href="#性能" aria-label="Permalink to “性能”">​</a></h4>',7)),n("p",null,[r[4]||(r[4]=e("儘管有桌面環境，Arch Linux 的性能總是更好。它總是令人感覺更快，因為它的內部並不臃腫。除此之外，",-1)),o(t,{href:"https://www.debugpoint.com/xfce-4-18-features/"},{default:a(()=>[...r[3]||(r[3]=[e("Xfce 桌面 4.18",-1)])]),_:1}),r[5]||(r[5]=e(" 在 “Cassini” 版本中還做了額外的性能優化，你可以在瀏覽桌面的時候感受到。",-1))]),r[35]||(r[35]=i('<p>在空閒狀態下，它使用了大約 700MB 的內存和平均 4% 的 CPU 佔用。這是性能基線。資源使用量可能會根據你打開的應用程序的數量而增加。在我之前對 EndeavourOS 的點評中，其性能表現也類似。</p><p>不僅如此，它在默認的 Xfce 安裝中只使用了 4GB 的磁盤空間。然而，你可能需要安裝額外的重型軟件，如 LibreOffice、GIMP 或 KDenlive，這將佔用更多磁盤空間。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/EndeavourOS-performance-22Cassini22.jpg" alt="EndeavourOS “Cassini” 的性能"></p><h4 id="在-endeavouros-中執行日常任務有多容易" tabindex="-1">在 EndeavourOS 中執行日常任務有多容易？ <a class="header-anchor" href="#在-endeavouros-中執行日常任務有多容易" aria-label="Permalink to “在 EndeavourOS 中執行日常任務有多容易？”">​</a></h4><p>EndeavourOS 的一大特點是一些基於 Python 的 GUI 工具，可以使你在 Arch Linux 中的生活變得簡單。例如，你可以從 Arch 和 EndeavourOS 的軟件倉庫中獲得更新通知、一鍵從 AUR 安裝軟件、一鍵更新鏡像和你的系統。你不需要從終端運行任何命令。這對 Arch Linux 的新用户來説是一個很大的幫助。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/One-click-installation-of-software.jpg" alt="一鍵安裝軟件"></p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Package-cleaner-and-update-manager.jpg" alt="軟件包清理器和更新管理器"></p><h4 id="處理滾動發佈的獨特方式-以實現穩定性" tabindex="-1">處理滾動發佈的獨特方式，以實現穩定性 <a class="header-anchor" href="#處理滾動發佈的獨特方式-以實現穩定性" aria-label="Permalink to “處理滾動發佈的獨特方式，以實現穩定性”">​</a></h4><p>Arch Linux 作為一個滾動發佈的發行版，往往會出現故障。例如，在 Arch 主倉庫的每個月的內核更新期間，一些系統可能會出現故障。由於它的受歡迎程度和開發者的主動性，如果出現問題，你會得到通知和相關的解決方法。</p>',9)),n("p",null,[r[7]||(r[7]=e("最近 Arch Linux 中的 GRUB 問題，給用户帶來了大量的啓動問題，EndeavourOS 團隊通過適當的溝通，給用户提供瞭解決方法，真的 ",-1)),o(t,{href:"https://endeavouros.com/news/full-transparency-on-the-grub-issue/"},{default:a(()=>[...r[6]||(r[6]=[e("處理得很好",-1)])]),_:1}),r[8]||(r[8]=e("。",-1))]),r[36]||(r[36]=n("p",null,"因此，如果你最終遇到一個不穩定的系統，你也不會真的迷失。",-1)),r[37]||(r[37]=n("p",null,"此外，Pacman 的配置已被定製過，使用 EndeavourOS 選擇的鏡像，以確保你的體驗是完美的。",-1)),r[38]||(r[38]=n("h4",{id:"對開源硬件和-arm-的正式支持",tabindex:"-1"},[e("對開源硬件和 ARM 的正式支持 "),n("a",{class:"header-anchor",href:"#對開源硬件和-arm-的正式支持","aria-label":"Permalink to “對開源硬件和 ARM 的正式支持”"},"​")],-1)),r[39]||(r[39]=n("p",null,"在這個 EndeavourOS “Cassini” 版本中，官方支持了 Pinebook Pro 筆記本電腦。該團隊在 Manjaro 軟件包的基礎上與 Pine64 團隊合作，為你提供了獨家的 Arch 軟件包，使該筆記本開箱即用。此外， EndeavourOS ARM 鏡像也可用於樹莓派 4。",-1)),r[40]||(r[40]=n("h4",{id:"社區幫助",tabindex:"-1"},[e("社區幫助 "),n("a",{class:"header-anchor",href:"#社區幫助","aria-label":"Permalink to “社區幫助”"},"​")],-1)),n("p",null,[r[10]||(r[10]=e("EndeavourOS 最大的好處之一是社區幫助 —— 這是即時的！這主要是指其專門的 ",-1)),o(t,{href:"https://endeavouros.com/community/"},{default:a(()=>[...r[9]||(r[9]=[e("Telegram 頻道",-1)])]),_:1}),r[11]||(r[11]=e("，在那裏你可以在幾分鐘內得到對你的 EndeavourOS 的任何問題的回應。我曾經去過這個頻道，管理員/貢獻者們都很友好，很有幫助。",-1))]),r[41]||(r[41]=n("p",null,"此外，你也可以從官方論壇和其他社交渠道獲得幫助。",-1)),r[42]||(r[42]=n("h3",{id:"總結",tabindex:"-1"},[e("總結 "),n("a",{class:"header-anchor",href:"#總結","aria-label":"Permalink to “總結”"},"​")],-1)),n("p",null,[r[13]||(r[13]=e("在結束對 EndeavourOS 的 ",-1)),o(t,{href:"https://endeavouros.com/news/cassini-packed-with-new-features-is-here/"},{default:a(()=>[...r[12]||(r[12]=[e("“Cassini” 版本",-1)])]),_:1}),r[14]||(r[14]=e(" 的點評時，我想説這是一個構建得最好的發行版，而且組織良好。開發者和團隊有一個建立通用的 Arch Linux 發行版的清晰路線圖。另外，通過對 ARM 和 Pinebook Pro 的支持以及其他舉措，其願景也很明確。",-1))]),r[43]||(r[43]=n("p",null,"總而言之，對於每一個希望在 Arch Linux 中擁有一個運行時間更長、更穩定的系統的人來説，這是一個完美的發行版。",-1)),n("p",null,[r[16]||(r[16]=e("你可以從 ",-1)),o(t,{href:"https://endeavouros.com/download/"},{default:a(()=>[...r[15]||(r[15]=[e("官方網站",-1)])]),_:1}),r[17]||(r[17]=e(" 下載 EndeavourOS。",-1))]),r[44]||(r[44]=n("p",null,"讓我們舉杯！",-1)),r[45]||(r[45]=n("hr",null,null,-1)),n("p",null,[r[19]||(r[19]=e("via: ",-1)),o(t,{href:"https://www.debugpoint.com/endeavouros-review/"},{default:a(()=>[...r[18]||(r[18]=[e("https://www.debugpoint.com/endeavouros-review/",-1)])]),_:1})]),n("p",null,[r[24]||(r[24]=e("作者：",-1)),o(t,{href:"https://www.debugpoint.com/author/admin1/"},{default:a(()=>[...r[20]||(r[20]=[e("Arindam",-1)])]),_:1}),r[25]||(r[25]=e(" 選題：",-1)),o(t,{href:"https://github.com/lkxed"},{default:a(()=>[...r[21]||(r[21]=[e("lkxed",-1)])]),_:1}),r[26]||(r[26]=e(" 譯者：",-1)),o(t,{href:"https://github.com/wxy"},{default:a(()=>[...r[22]||(r[22]=[e("wxy",-1)])]),_:1}),r[27]||(r[27]=e(" 校對：",-1)),o(t,{href:"https://github.com/wxy"},{default:a(()=>[...r[23]||(r[23]=[e("wxy",-1)])]),_:1})]),n("p",null,[r[30]||(r[30]=e("本文由 ",-1)),o(t,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...r[28]||(r[28]=[e("LCTT",-1)])]),_:1}),r[31]||(r[31]=e(" 原創編譯，",-1)),o(t,{href:"https://linux.cn/"},{default:a(()=>[...r[29]||(r[29]=[e("Linux中國",-1)])]),_:1}),r[32]||(r[32]=e(" 榮譽推出",-1))])])}const g=s(l,[["render",f]]);export{A as __pageData,g as default};
